/**
 * @name Command injection in tqdm
 * @description Command injection via subprocess or os.system with user-controlled input
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find command execution sinks
    exists(API::CallNode call |
      // Check for os.system calls
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // Check for subprocess.call, subprocess.run, etc.
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // Check for subprocess.Popen constructor
      call = API::moduleImport("subprocess").getMember("Popen!").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Code injection in tqdm
 * @description Using eval, exec, or compile with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for eval, exec, compile calls
    exists(API::CallNode call |
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"

/**
 * @name Cross-site scripting (XSS) in tqdm
 * @description Cross-site scripting via HTML output with user-controlled input
 * @kind path-problem
 * @problem.severity error
 * @id py/xss
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for HTML output operations
    exists(API::CallNode call |
      // IPython/Notebook display functions
      call = API::moduleImport("IPython").getMember("display").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // HTML generation
      call = API::moduleImport("html").getMember(["escape", "unescape"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // Notebook HTML output
      call = API::moduleImport("IPython.core.display").getMember("HTML").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XssFlow = TaintTracking::Global<XssConfig>;
import XssFlow::PathGraph

from XssFlow::PathNode source, XssFlow::PathNode sink
where XssFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Cross-site scripting from $@.", source.getNode(), "user input"
